32	    @Mapping(target = "salutation", source = "owner", qualifiedByName = "formatSalutation")
33	    @Mapping(target = "displayName", source = "owner", qualifiedByName = "formatDisplayName")
34	    @Mapping(target = "initials", source = "owner", qualifiedByName = "formatInitials")
35	    @Mapping(target = "telephoneDisplay", source = "owner", qualifiedByName = "formatTelephoneDisplay")
36	    @Mapping(target = "checkDigit", source = "owner", qualifiedByName = "formatCheckDigit")
