67	    /**
68	     * Formats an owner's name as {@code 'LastName, FirstName'} from the stored first and
69	     * last names, as required by the API's read-only {@code displayName} field.
70	     *
71	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
72	     * applied only where referenced via {@code qualifiedByName}.
73	     */
74	    @Named("formatDisplayName")
75	    default String formatDisplayName(Owner owner) {
76	        if (owner == null) {
77	            return null;
78	        }
79	        return owner.getLastName() + ", " + owner.getFirstName();
