93	            return null;
94	        }
95	        return initial(owner.getFirstName()) + initial(owner.getLastName());
96	    }
97	
98	    /**
99	     * Formats an owner's stored E.164 telephone for human display, as required by the API's
100	     * read-only {@code telephoneDisplay} field: the country code (with its leading {@code '+'}),
101	     * a space, then the national digits grouped in threes (e.g. {@code '+61 412 345 678'}). The
102	     * raw {@code telephone} field keeps its canonical E.164 form. Returns {@code null} when no
103	     * telephone is present.
104	     *
105	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
106	     * applied only where referenced via {@code qualifiedByName}.
107	     */
108	    @Named("formatTelephoneDisplay")
109	    default String formatTelephoneDisplay(Owner owner) {
110	        if (owner == null) {
111	            return null;
112	        }
113	        return TelephoneNormalizer.toDisplay(owner.getTelephone());
114	    }
115	
116	    /**
117	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where
118	     * {@code customerCode} is the owner's {@code '<REGION>-<HASH8>'} customer code and
119	     * {@code YY} is the last two digits of the registration date's year (e.g.
120	     * {@code 'NSW-1A2B3C4D-M26'}), as required by the API's read-only
121	     * {@code membershipNumber} field. Returns {@code null} when either the customer code
122	     * or registration date is absent.
123	     *
124	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
125	     * applied only where referenced via {@code qualifiedByName}.
126	     */
127	    @Named("formatMembershipNumber")
128	    default String formatMembershipNumber(Owner owner) {
129	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
130	            return null;
131	        }
132	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
133	    }
134	
135	    /**
136	     * Computes an owner's check digit, as required by the API's read-only {@code checkDigit}
137	     * field: a single Luhn check digit (0-9) over the digits contained in the owner's customer
138	     * code. Returns {@code null} when the customer code is absent.
139	     *
140	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
141	     * applied only where referenced via {@code qualifiedByName}.
142	     */
143	    @Named("formatCheckDigit")
144	    default Integer formatCheckDigit(Owner owner) {
145	        if (owner == null || owner.getCustomerCode() == null) {
146	            return null;
147	        }
148	        return LuhnCheckDigit.compute(owner.getCustomerCode());
149	    }
150	
151	    /**
152	     * Computes an owner's membership points, as required by the API's read-only
153	     * {@code membershipPoints} field: starting at 0, plus 2 when an email address is present,
154	     * plus 1 when the owner has no namesakes ({@code namesakeCount} is 0), plus 2 for a household
155	     * of 3 or more members, plus 3 when the owner's tenure exceeds 365 days (more than a year
156	     * since the registration date).
157	     *
158	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
159	     * applied only where referenced via {@code qualifiedByName}.
160	     */
161	    @Named("formatMembershipPoints")
162	    default Integer formatMembershipPoints(Owner owner) {
163	        if (owner == null) {
164	            return null;
165	        }
166	        int points = 0;
167	        if (owner.getEmail() != null && !owner.getEmail().isEmpty()) {
168	            points += 2;
169	        }
170	        if (owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0) {
171	            points += 1;
172	        }
173	        if (owner.getHouseholdMemberCount() != null && owner.getHouseholdMemberCount() >= 3) {
174	            points += 2;
175	        }
176	        if (owner.getRegistrationDate() != null
177	                && ChronoUnit.DAYS.between(owner.getRegistrationDate(), LocalDate.now()) > 365) {
178	            points += 3;
179	        }
180	        return points;
181	    }
182	
183	    /**
184	     * Derives an owner's membership level, as required by the API's read-only
185	     * {@code membershipLevel} field: a value from 1 to 4 mapped from the owner's
186	     * {@link #formatMembershipPoints membership points} — level 1 for 0-1 points, level 2 for
187	     * 2-3 points, level 3 for 4-5 points, and level 4 for 6 or more points.
188	     *
189	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
190	     * applied only where referenced via {@code qualifiedByName} (and when called directly, e.g.
191	     * to record the membership level on the create audit line).
192	     */
193	    @Named("formatMembershipLevel")
194	    default Integer formatMembershipLevel(Owner owner) {
195	        if (owner == null) {
196	            return null;
197	        }
198	        int points = formatMembershipPoints(owner);
199	        if (points <= 1) {
200	            return 1;
201	        }
202	        if (points <= 3) {
203	            return 2;
204	        }
205	        if (points <= 5) {
206	            return 3;
207	        }
208	        return 4;
209	    }
210	
211	    /**
212	     * Derives an owner's locality, as required by the API's read-only {@code locality} field:
213	     * the {@code REGION} segment of the owner's {@code '<REGION>-<HASH8>'} customer code, so the
214	     * locality is read from the same region-and-hash identity that the customer code encodes.
215	     * When no customer code is present (e.g. an owner that predates the code), the region is
216	     * resolved directly from the postcode (falling back to the city-to-region table, else
217	     * {@code 'UNKNOWN'}), which yields the same region the code would have carried.
218	     *
219	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
220	     * applied only where referenced via {@code qualifiedByName}.
221	     */
222	    @Named("formatLocality")
223	    default String formatLocality(Owner owner) {
224	        if (owner == null) {
225	            return null;
226	        }
227	        String customerCode = owner.getCustomerCode();
228	        if (customerCode != null) {
229	            int dash = customerCode.indexOf('-');
230	            if (dash > 0) {
231	                return customerCode.substring(0, dash);
232	            }
233	        }
234	        return LocalityResolver.resolve(owner.getCity(), owner.getPostcode());
235	    }
236	
237	    /**
238	     * Derives an owner's timezone, as required by the API's read-only {@code timezone} field:
239	     * the IANA timezone name for the owner's {@link #formatLocality locality}/region, via the
240	     * fixed region-to-timezone table ({@code NSW -> Australia/Sydney},
241	     * {@code VIC -> Australia/Melbourne}, {@code QLD -> Australia/Brisbane}). Returns
242	     * {@code null} when the region has no mapped timezone (e.g. {@code 'UNKNOWN'}).
243	     *
244	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
245	     * applied only where referenced via {@code qualifiedByName}.
246	     */
247	    @Named("formatTimezone")
248	    default String formatTimezone(Owner owner) {
249	        if (owner == null) {
250	            return null;
251	        }
252	        return LocalityResolver.timezone(formatLocality(owner));
253	    }
254	
255	    /**
256	     * Derives an owner's preferred contact channel, as required by the API's read-only
257	     * {@code contactPreference} field: {@code 'EMAIL'} when an email address is present,
258	     * otherwise {@code 'PHONE'}.
259	     *
260	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
261	     * applied only where referenced via {@code qualifiedByName}.
262	     */
263	    @Named("formatContactPreference")
264	    default String formatContactPreference(Owner owner) {
265	        if (owner == null) {
266	            return null;
267	        }
268	        return owner.getEmail() != null && !owner.getEmail().isEmpty() ? "EMAIL" : "PHONE";
269	    }
270	
271	    /**
272	     * Derives an owner's age band, as required by the API's read-only {@code ageBand} field:
273	     * the owner's age in whole years at the registration date, mapped to {@code 'MINOR'} (under
274	     * 18), {@code 'ADULT'} (18 to 64) or {@code 'SENIOR'} (65 or over). Returns {@code null} when
275	     * no birth date was supplied (so the field is absent), or when no registration date is yet
276	     * known against which to compute the age.
277	     *
278	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
279	     * applied only where referenced via {@code qualifiedByName}.
280	     */
281	    @Named("formatAgeBand")
282	    default String formatAgeBand(Owner owner) {
283	        if (owner == null || owner.getBirthDate() == null || owner.getRegistrationDate() == null) {
284	            return null;
285	        }
286	        int age = Period.between(owner.getBirthDate(), owner.getRegistrationDate()).getYears();
287	        if (age < 18) {
288	            return "MINOR";
289	        }
290	        if (age < 65) {
291	            return "ADULT";
292	        }
293	        return "SENIOR";
294	    }
295	
296	    private static String initial(String name) {
297	        if (name == null || name.isEmpty()) {
298	            return "";
299	        }
300	        return Character.toUpperCase(name.charAt(0)) + ".";
301	    }
302	
303	    Owner toOwner(OwnerDto ownerDto);
304	
305	    @Mapping(target = "id", ignore = true)
306	    @Mapping(target = "pets", ignore = true)
307	    @Mapping(target = "addressLine1", ignore = true)
308	    @Mapping(target = "addressLine2", ignore = true)
309	    @Mapping(target = "address", ignore = true)
310	    @Mapping(target = "telephone", source = "telephone", qualifiedByName = "normalizeTelephone")
311	    @Mapping(target = "email", source = "email", qualifiedByName = "normalizeEmail")
312	    @Mapping(target = "title", source = "title", qualifiedByName = "mapTitle")
313	    Owner toOwner(OwnerFieldsDto ownerDto);
314	
315	    /**
316	     * Unwraps the owner-fields' optional honorific {@code title} enum into the stored
317	     * {@code String} form (its canonical value, e.g. {@code 'DR'}), or {@code null} when no
318	     * title was supplied. This is the single place the inbound title conversion lives: it runs
319	     * on the create path via {@link #toOwner(OwnerFieldsDto)} and is called directly on the
320	     * update path, keeping both consistent.
321	     *
322	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
323	     * applied only where referenced via {@code qualifiedByName}.
324	     */
325	    @Named("mapTitle")
326	    default String mapTitle(OwnerFieldsDto.TitleEnum title) {
327	        return title == null ? null : title.getValue();
328	    }
329	
330	    /**
331	     * Sets an owner's structured and composed address fields from the supplied owner-fields,
332	     * normalizing each. This is the single place the structured-field normalization rule lives: it
333	     * runs automatically after {@link #toOwner(OwnerFieldsDto)} via {@code @AfterMapping}, and is
334	     * called directly on the update path to keep both create and update consistent.
335	     *
336	     * <p>{@code addressLine1} and {@code addressLine2} are stored in their normalized forms and
337	     * {@code address} is set to the {@link #composeAddress composed} effective address.
338	     */
339	    @AfterMapping
340	    default void applyAddressFields(OwnerFieldsDto ownerDto, @MappingTarget Owner owner) {
341	        if (ownerDto == null) {
342	            return;
343	        }
344	        owner.setAddressLine1(normalizeAddress(ownerDto.getAddressLine1()));
345	        owner.setAddressLine2(normalizeAddress(ownerDto.getAddressLine2()));
346	        owner.setAddress(composeAddress(ownerDto));
347	    }
348	
349	    /**
350	     * Composes the effective, normalized postal address for an owner from the supplied fields,
351	     * preferring the structured form over the flat one. When a non-blank {@code addressLine1} is
352	     * present, the result is the normalized {@code addressLine1} with the normalized
353	     * {@code addressLine2} appended after a single space when an {@code addressLine2} is present;
354	     * otherwise it is the normalized flat {@code address}. Each part is normalized through
355	     * {@link #normalizeAddress} (trim, collapse whitespace, upper-case, expand {@code ST -> STREET},
356	     * {@code RD -> ROAD}, {@code AVE -> AVENUE}).
357	     */
358	    default String composeAddress(OwnerFieldsDto ownerDto) {
359	        if (ownerDto == null) {
360	            return null;
361	        }
362	        String line1 = normalizeAddress(ownerDto.getAddressLine1());
363	        if (line1 != null && !line1.isEmpty()) {
364	            String line2 = normalizeAddress(ownerDto.getAddressLine2());
365	            return (line2 != null && !line2.isEmpty()) ? line1 + " " + line2 : line1;
366	        }
367	        return normalizeAddress(ownerDto.getAddress());
368	    }
369	
370	    /**
371	     * Normalizes a postal address into a canonical form: surrounding whitespace is trimmed and
372	     * internal runs of whitespace collapsed to a single space, the value is upper-cased and common
373	     * abbreviations are expanded as whole tokens ({@code ST -> STREET}, {@code RD -> ROAD},
374	     * {@code AVE -> AVENUE}). So {@code '  12  main  st '} is stored and returned as
375	     * {@code '12 MAIN STREET'}.
376	     *
377	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
378	     * only where referenced via {@code qualifiedByName}.
379	     */
380	    @Named("normalizeAddress")
381	    default String normalizeAddress(String address) {
382	        return AddressNormalizer.normalize(address);
383	    }
384	
385	    /**
386	     * Normalizes a telephone number into canonical E.164 form: a leading {@code '+'} and country
387	     * code are kept when present, otherwise country code {@code '+61'} is assumed and a single
388	     * leading {@code '0'} is dropped from the national digits; spaces, dashes and brackets are
389	     * stripped and the result must contain 8 to 15 digits after the {@code '+'}. So
390	     * {@code '0412 345 678'} is stored and returned as {@code '+61412345678'}.
391	     *
392	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is applied
393	     * only where referenced via {@code qualifiedByName} (and when called directly, e.g. on update).
394	     *
395	     * @throws org.springframework.samples.petclinic.util.InvalidTelephoneException if the number
396	     *         cannot form a valid E.164 value (handled as a 400 Bad Request).
397	     */
398	    @Named("normalizeTelephone")
399	    default String normalizeTelephone(String telephone) {
400	        return TelephoneNormalizer.toE164(telephone);
401	    }
402	
403	    /**
404	     * Normalizes an email address by lower-casing it, so it is stored and returned in a
405	     * canonical form. The schema-level {@code format: email} on {@code OwnerFieldsDto.email}
406	     * guarantees any value present is a syntactically valid address.
407	     *
408	     * <p>{@code @Named} keeps this out of MapStruct's automatic method selection, so it is
409	     * applied only where referenced via {@code qualifiedByName} (and when called directly,
410	     * e.g. on update).
411	     */
412	    @Named("normalizeEmail")
413	    default String normalizeEmail(String email) {
414	        return email == null ? null : email.toLowerCase(Locale.ROOT);
415	    }
416	
417	    List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
418	
419	    Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
420	
421	    default OwnerPageDto toOwnerPageDto(@NonNull Page<Owner> ownerPage) {
422	        OwnerPageDto ownerPageDto = new OwnerPageDto();
423	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
424	        ownerPageDto.setPage(ownerPage.getNumber());
425	        ownerPageDto.setSize(ownerPage.getSize());
426	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
427	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
428	        return ownerPageDto;
429	    }
430	}
